# plots-export-ts.py : writes docs/city_plots_tiled.json into src/roads/debug/PlotData.ts (used by the key 5 plot layer). Run: python3 tools/plots-export-ts.py
import json
d = json.load(open('docs/city_plots_tiled.json')); rows = []
for p in d['plots']:
    flat = ','.join(f'{v:g}' for xz in p['poly'] for v in xz)
    rows.append(f"[{1 if p['tiny'] else 0},{p['area']},{flat}]")
open('src/roads/debug/PlotData.ts', 'w').write(
    "// GENERATED by tools/plots-export-ts.py from docs/city_plots_tiled.json - do not edit. Each row: [tiny(0/1), area m2, x0, z0, x1, z1, ...] one closed plot outline.\n"
    "export const PLOTS: number[][] = [\n" + ',\n'.join(rows) + '\n];\n')
print('plots', len(rows))
